select id, order_id, carrier, shipped_date, delivered_date, cost, status, ntile(3) over (partition by order_id order by cost, id) as cost_bucket, min(cost) over (partition by order_id) as order_id_min_cost, avg(cost) over (order by cost, id rows between 6 preceding and 1 preceding) as cost_avg_6_prior, last_value(carrier) ignore nulls over (partition by status order by cost, id rows between unbounded preceding and current row) as last_known_carrier, sum(cost) over (partition by order_id order by shipped_date, id rows between unbounded preceding and current row) as cumulative_cost from shipments
